package com.dukaops.backend.settings;
import jakarta.validation.Valid; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import com.dukaops.backend.auth.TenantUserPrincipal; import com.dukaops.backend.settings.dto.*;
@RestController @RequestMapping("/api/settings") public class SettingsController {private final SettingsService service; private final ProfileService profile; public SettingsController(SettingsService s,ProfileService p){service=s;profile=p;} @GetMapping("/business") public BusinessSettingsResponse get(@AuthenticationPrincipal TenantUserPrincipal p){return service.get(p);} @PutMapping("/business") public BusinessSettingsResponse update(@AuthenticationPrincipal TenantUserPrincipal p,@Valid @RequestBody BusinessSettingsRequest r){return service.update(p,r);} @GetMapping("/preferences") public PreferencesResponse preferences(@AuthenticationPrincipal TenantUserPrincipal p){return service.preferences(p);} @PutMapping("/preferences") public PreferencesResponse updatePreferences(@AuthenticationPrincipal TenantUserPrincipal p,@Valid @RequestBody PreferencesRequest r){return service.updatePreferences(p,r);} @GetMapping("/profile") public ProfileResponse profile(@AuthenticationPrincipal TenantUserPrincipal p){return profile.get(p);} @PutMapping("/profile") public ProfileResponse updateProfile(@AuthenticationPrincipal TenantUserPrincipal p,@Valid @RequestBody ProfileRequest r){return profile.update(p,r);} @PutMapping("/change-password") public void password(@AuthenticationPrincipal TenantUserPrincipal p,@Valid @RequestBody ChangePasswordRequest r){profile.password(p,r);}}
